/**
 * Getting readable text out of the documents people actually forward.
 *
 * The reader takes text and it takes images and PDFs as bytes; everything else has to become text
 * on the way in. That is a job with no judgement in it — a `.docx` is a zip with an XML file
 * inside, an `.eml` is headers and a body with a stated encoding — so it belongs here, in the
 * deterministic half, rather than being handed to a model to guess at.
 *
 * Every format degrades the same way: unreadable bytes come back as `null`, and the funnel says
 * it couldn't read the file rather than passing rubbish to the reader.
 */

import { strFromU8, unzipSync } from 'fflate';

/** The formats this can turn into text, beyond plain text itself. */
export type DocumentFormat = 'docx' | 'eml' | 'rtf' | 'html' | 'text';

const BY_EXTENSION: Record<string, DocumentFormat> = {
  docx: 'docx',
  eml: 'eml',
  msg: 'eml',
  rtf: 'rtf',
  html: 'html',
  htm: 'html',
  txt: 'text',
  md: 'text',
  csv: 'text',
};

/** Which reader a file name calls for, or `undefined` when none of them fits. */
export function documentFormat(fileName: string | undefined): DocumentFormat | undefined {
  const name = fileName ?? '';
  const dot = name.lastIndexOf('.');
  return dot < 0 ? undefined : BY_EXTENSION[name.slice(dot + 1).toLowerCase()];
}

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** Base64 → bytes, written out rather than borrowed: `atob` isn't everywhere this runs. */
function fromBase64(value: string): Uint8Array {
  const clean = value.replace(/[^A-Za-z0-9+/]/g, '');
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4));
  let held = 0;
  let bits = 0;
  let at = 0;
  for (const character of clean) {
    const index = ALPHABET.indexOf(character);
    if (index < 0) continue;
    held = (held << 6) | index;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[at++] = (held >> bits) & 0xff;
    }
  }
  return out.subarray(0, at);
}

/** `=E2=80=99` and soft line breaks, as email bodies have used since forever. */
function fromQuotedPrintable(value: string): string {
  const joined = value.replace(/=\r?\n/g, '');
  const bytes: number[] = [];
  for (let at = 0; at < joined.length; at += 1) {
    const character = joined[at] ?? '';
    if (character === '=' && at + 2 < joined.length) {
      const hex = joined.slice(at + 1, at + 3);
      if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
        bytes.push(parseInt(hex, 16));
        at += 2;
        continue;
      }
    }
    bytes.push(character.charCodeAt(0));
  }
  return strFromU8(new Uint8Array(bytes));
}

/**
 * `=?UTF-8?Q?Sam=E2=80=99s_recital?=` — how a mailer carries anything but ASCII in a header. The
 * subject line names the event as often as the body does, so a mangled one is a real loss.
 */
function decodeEncodedWords(value: string): string {
  return value.replace(/=\?[^?]+\?([QB])\?([^?]*)\?=/gi, (_, encoding: string, text: string) =>
    encoding.toUpperCase() === 'B'
      ? strFromU8(fromBase64(text))
      : fromQuotedPrintable(text.replace(/_/g, ' ')),
  );
}

const ENTITIES: Record<string, string> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
  nbsp: ' ',
};

/** Markup out, text in — good enough to read an event out of, which is all this is for. */
function fromMarkup(html: string): string {
  return html
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>|<\/p>|<\/div>|<\/tr>|<\/li>/gi, '\n')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&#(\d+);/g, (_, code: string) => String.fromCharCode(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code: string) => String.fromCharCode(parseInt(code, 16)))
    .replace(/&([a-z]+);/gi, (whole, name: string) => ENTITIES[name.toLowerCase()] ?? whole)
    .replace(/[ \t\u00a0]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

/** RTF is control words and groups; the text is what's left when they're gone. */
function fromRtf(rtf: string): string {
  return rtf
    .replace(/\\'([0-9a-f]{2})/gi, (_, hex: string) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/\\par[d]?\b/g, '\n')
    .replace(/\\line\b/g, '\n')
    .replace(/\\[a-z]+-?\d*\s?/gi, '')
    .replace(/[{}]/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

/**
 * A `.docx` is a zip; the words live in `word/document.xml` as `<w:t>` runs, and paragraphs end
 * at `</w:p>`. Nothing else in the package matters for reading an event out of it.
 */
function fromDocx(bytes: Uint8Array): string | null {
  let document: Uint8Array | undefined;
  try {
    const files = unzipSync(bytes, { filter: (file) => file.name === 'word/document.xml' });
    document = files['word/document.xml'];
  } catch {
    return null; // not a zip, or a broken one
  }
  if (document === undefined) return null;
  const xml = strFromU8(document);
  const paragraphs = xml
    .split(/<\/w:p>/)
    .map((paragraph) =>
      [...paragraph.matchAll(/<w:t(?:\s[^>]*)?>([\s\S]*?)<\/w:t>/g)]
        .map((match) => match[1] ?? '')
        .join(''),
    )
    .map((line) => fromMarkup(line))
    .filter((line) => line !== '');
  return paragraphs.length === 0 ? null : paragraphs.join('\n');
}

/** The header block and the body, split at the first blank line. */
function splitHeaders(raw: string): { headers: Record<string, string>; body: string } {
  const boundary = raw.search(/\r?\n\r?\n/);
  const head = boundary < 0 ? raw : raw.slice(0, boundary);
  const body = boundary < 0 ? '' : raw.slice(boundary).replace(/^\r?\n\r?\n/, '');
  const headers: Record<string, string> = {};
  // Unfold continuation lines first — a long Subject is wrapped and indented.
  for (const line of head.replace(/\r?\n[ \t]+/g, ' ').split(/\r?\n/)) {
    const at = line.indexOf(':');
    if (at > 0) {
      headers[line.slice(0, at).trim().toLowerCase()] = decodeEncodedWords(
        line.slice(at + 1).trim(),
      );
    }
  }
  return { headers, body };
}

/** Decode one body part according to what its own headers said it was encoded with. */
function decodePart(headers: Record<string, string>, body: string): string {
  const encoding = (headers['content-transfer-encoding'] ?? '').toLowerCase();
  const decoded =
    encoding === 'base64'
      ? strFromU8(fromBase64(body))
      : encoding === 'quoted-printable'
        ? fromQuotedPrintable(body)
        : body;
  return (headers['content-type'] ?? '').toLowerCase().includes('text/html')
    ? fromMarkup(decoded)
    : decoded;
}

/**
 * An email as the funnel should read it: who it's from, what it's about, and what it says — the
 * subject line carries the event as often as the body does.
 */
function fromEml(raw: string): string | null {
  const { headers, body } = splitHeaders(raw);
  const boundary = /boundary="?([^";\r\n]+)"?/i.exec(headers['content-type'] ?? '')?.[1];

  let text = '';
  if (boundary === undefined) {
    text = decodePart(headers, body);
  } else {
    // Multipart: prefer the plain-text alternative, fall back to whatever the last part holds.
    const parts = body.split(new RegExp(`--${boundary.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`));
    const decoded = parts
      .map((part) => splitHeaders(part.replace(/^\r?\n/, '')))
      .filter((part) => (part.headers['content-type'] ?? 'text/plain').includes('text/'))
      .map((part) => ({
        plain: (part.headers['content-type'] ?? 'text/plain').includes('text/plain'),
        text: decodePart(part.headers, part.body),
      }))
      .filter((part) => part.text.trim() !== '');
    text = (decoded.find((part) => part.plain) ?? decoded[0])?.text ?? '';
  }

  const lines = [
    headers.subject === undefined ? undefined : `Subject: ${headers.subject}`,
    headers.from === undefined ? undefined : `From: ${headers.from}`,
    headers.date === undefined ? undefined : `Sent: ${headers.date}`,
    text.trim(),
  ].filter((line): line is string => line !== undefined && line !== '');
  return lines.length === 0 ? null : lines.join('\n');
}

/**
 * Turn a document's bytes into the text the reader takes, or `null` when the bytes aren't what
 * the name claimed. The caller decides what to say about a `null`.
 */
export function documentTextFrom(fileName: string | undefined, bytes: Uint8Array): string | null {
  const format = documentFormat(fileName);
  if (format === undefined) return null;
  if (format === 'docx') return fromDocx(bytes);

  const raw = strFromU8(bytes);
  const text =
    format === 'eml'
      ? fromEml(raw)
      : format === 'rtf'
        ? fromRtf(raw)
        : format === 'html'
          ? fromMarkup(raw)
          : raw;
  const trimmed = text?.trim() ?? '';
  return trimmed === '' ? null : trimmed;
}
