/**
 * The site's funnel: anything with an event in it, read here, on this machine.
 *
 * The app's funnel sends what it reads to a language model. A static site has no server to hold a
 * key, so this one doesn't use a model at all: text formats are parsed outright, pictures are read
 * with a recogniser and the rest (PDFs, decks, spreadsheets, ebooks) with a converter — both
 * fetched on demand — and the text is turned into events by `parseEvents`. Everything downstream — the batch, the flags, the duplicate check — is the
 * same code the app runs.
 *
 * The consequence, stated plainly on the page: regular text (a fixture list, a flyer, "dentist
 * tomorrow at 9") is read well, and prose is not. Nothing about what you drop in leaves the
 * browser.
 */

import {
  buildIntakeBatch,
  classifyIntakeMedia,
  documentFormat,
  documentTextFrom,
  parseEvents,
  type IntakeBatch,
} from '@project/core';
import { todayLocal } from '@project/event-creator-web';

import { convertibleFormat, createConverter } from './convert';
import { createOcr } from './ocr';

/** What the funnel made of a file, before any of it becomes events. */
interface ReadFile {
  readonly text: string | null;
  /** What to tell the user when there was nothing to read. */
  readonly problem?: IntakeProblem;
}

export type IntakeProblem = 'unreadable' | 'scanned' | 'noEvents';
export type IntakeProgress = 'loading' | 'reading' | 'parsing';

const decoder = new TextDecoder();

/** One recogniser for the page, so a second picture reuses the first one's worker. */
const ocr = createOcr();

/** One converter for the page, for the same reason. */
const converter = createConverter();

async function readFile(
  file: File,
  progress: (stage: IntakeProgress) => void,
  language: string,
): Promise<ReadFile> {
  const media = classifyIntakeMedia({
    ...(file.type ? { mimeType: file.type } : {}),
    ...(file.name ? { fileName: file.name } : {}),
  });

  if (media.kind === 'text' || documentFormat(file.name) !== undefined) {
    progress('reading');
    const bytes = new Uint8Array(await file.arrayBuffer());
    const text = documentTextFrom(file.name, bytes) ?? decoder.decode(bytes);
    return text.trim() === '' ? { text: null, problem: 'unreadable' } : { text };
  }

  if (media.kind === 'image') {
    progress('loading');
    // Read here, by a recogniser this site serves itself — see `ocr.ts` for why it is not a CDN's.
    const text = await ocr.read(file, () => progress('reading'), language);
    return text === null
      ? {
          text: null,
          problem: 'unreadable',
        }
      : { text };
  }

  const format = convertibleFormat(file.name);
  if (format !== undefined) {
    progress('loading');
    // Read here too, by a converter this site serves itself — see `convert.ts`. A PDF that is a
    // photograph of a page is the one kind that stays unread, and it gets its own answer.
    const read = await converter.read(file, format, () => progress('reading'));
    return read.text === null
      ? {
          text: null,
          problem: read.failure === 'scanned' ? 'scanned' : 'unreadable',
        }
      : { text: read.text };
  }

  if (media.kind === 'audio') {
    return {
      text: null,
      problem: 'unreadable',
    };
  }

  return { text: null, problem: 'unreadable' };
}

export interface FunnelResult {
  readonly batch: IntakeBatch;
  /** What to say when nothing came of it. */
  readonly problem?: IntakeProblem;
}

let runs = 0;

/** Read whatever was typed and whatever was attached, and fill in a form for each event found. */
export async function runFunnel(
  typed: string,
  file: File | null,
  progress: (stage: IntakeProgress) => void = () => undefined,
  language = 'en',
): Promise<FunnelResult> {
  const attached = file === null ? { text: null } : await readFile(file, progress, language);
  progress('parsing');
  const parts = [attached.text, typed.trim()].filter(
    (part): part is string => part !== null && part !== '',
  );
  const today = todayLocal();
  const media = classifyIntakeMedia({ text: parts.join('\n') || 'x' });
  const id = `run-${(runs += 1)}`;

  if (parts.length === 0) {
    return {
      batch: buildIntakeBatch({ id, media, extractions: [] }),
      ...(attached.problem === undefined ? {} : { problem: attached.problem }),
    };
  }

  // No zone, deliberately — the same stance the builder takes. "3pm" on a fixture list means 3pm
  // where the match is, and a zone-less event does exactly that in every calendar; stamping the
  // browser's zone would make a claim about the reader instead of the event.
  const extractions = parseEvents(parts.join('\n'), { today, locale: language });
  const batch = buildIntakeBatch({ id, media, extractions });
  const problem = extractions.length === 0 ? (attached.problem ?? 'noEvents') : attached.problem;
  return { batch, ...(problem === undefined ? {} : { problem }) };
}
