/**
 * Reading events out of text with no model at all.
 *
 * The funnel's reader is a language model, which needs a key, a network and money. Plenty of what
 * people actually paste doesn't need one: a fixture list, a concert flyer, a line like "dentist
 * tomorrow at 9". Those are regular enough to parse, and a parser runs anywhere — including a
 * static site with no backend, which is the whole point of this module.
 *
 * It returns the same {@link IntakeExtraction} shape the model path does, so everything
 * downstream — the batch, the flags, the duplicate check, the confirm — is the same code.
 *
 * It is deliberately literal. Where the text is regular it is exact; where it isn't, it says so
 * by leaving the date or time unstated, which flags the form for a look rather than inventing
 * something. Prose ("the Saturday of that week") is a model's job, and this doesn't pretend.
 */

import type { EventDraft } from '@project/event-format';

import type { IntakeExtraction } from './batch';
import {
  CALENDAR_LANGUAGES,
  calendarLocale,
  calendarWords,
  localizedDate,
  localizedTime,
} from './parse-locales';

export interface ParseEventsOptions {
  /** Today, as `YYYY-MM-DD` — the anchor for "tomorrow" and for a date with no year. */
  readonly today: string;
  /** Input language; defaults to English. All processing remains local. */
  readonly locale?: string;
  /** The zone timed events are written in; omitted means floating. */
  readonly timeZone?: string;
}

const MONTHS = [
  'january',
  'february',
  'march',
  'april',
  'may',
  'june',
  'july',
  'august',
  'september',
  'october',
  'november',
  'december',
];
const WEEKDAYS = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];

const MONTH_WORD =
  '(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)(?![a-z])';
const WEEKDAY_WORD =
  '(mon(?:day)?|tue(?:s(?:day)?)?|wed(?:nesday)?|thu(?:rs(?:day)?)?|fri(?:day)?|sat(?:urday)?|sun(?:day)?)(?![a-z])';

/** What a date expression found in a line came to. */
interface FoundDate {
  readonly date: string;
  /** The text it was read from, so the title can have it removed. */
  readonly source: string;
  /** False when the day had to be worked out rather than read — an ambiguous numeric date. */
  readonly stated: boolean;
}

interface FoundTime {
  readonly start: string;
  readonly end?: string;
  readonly source: string;
}

const pad = (value: number): string => String(value).padStart(2, '0');
const iso = (year: number, month: number, day: number): string =>
  `${year}-${pad(month)}-${pad(day)}`;

/** Day-of-week for a `YYYY-MM-DD`, read in UTC so no zone can shift it. */
function weekdayOf(date: string): number {
  const [year, month, day] = date.split('-').map(Number);
  return new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, day ?? 1)).getUTCDay();
}

function shiftDays(date: string, by: number): string {
  const [year, month, day] = date.split('-').map(Number);
  const when = new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, (day ?? 1) + by));
  return iso(when.getUTCFullYear(), when.getUTCMonth() + 1, when.getUTCDate());
}

/** Is this a day that exists? 31 September is not. */
function real(year: number, month: number, day: number): boolean {
  const when = new Date(Date.UTC(year, month - 1, day));
  return (
    when.getUTCFullYear() === year && when.getUTCMonth() === month - 1 && when.getUTCDate() === day
  );
}

/**
 * The year to read a bare "12 Sep" as: the one that puts it just ahead of today. A month barely
 * past is read as this year (a flyer printed last week), anything further back as next year.
 */
function yearFor(month: number, day: number, today: string): number {
  const thisYear = Number(today.slice(0, 4));
  for (const year of [thisYear, thisYear + 1, thisYear - 1]) {
    if (!real(year, month, day)) continue;
    const candidate = iso(year, month, day);
    if (candidate >= shiftDays(today, -30)) return year;
  }
  return thisYear;
}

/** Every date expression this understands, tried in order of how sure it is. */
function findDate(line: string, today: string): FoundDate | undefined {
  const lower = line.toLowerCase();

  const isoMatch = /\b(\d{4})-(\d{2})-(\d{2})\b/.exec(line);
  if (isoMatch) {
    const [source, year, month, day] = isoMatch;
    if (real(Number(year), Number(month), Number(day))) {
      return { date: iso(Number(year), Number(month), Number(day)), source, stated: true };
    }
  }

  // "12 September 2026", "Sat 12 Sep", "12th Sept"
  const dayFirst = new RegExp(
    `\\b(?:${WEEKDAY_WORD}\\.?,?\\s+)?(\\d{1,2})(?:st|nd|rd|th)?\\s+${MONTH_WORD}\\.?(?:\\s+(\\d{4}))?`,
    'i',
  ).exec(line);
  if (dayFirst) {
    const day = Number(dayFirst[2]);
    const month = MONTHS.findIndex((name) => name.startsWith(dayFirst[3]!.toLowerCase())) + 1;
    const year = dayFirst[4] === undefined ? yearFor(month, day, today) : Number(dayFirst[4]);
    if (month > 0 && real(year, month, day)) {
      return { date: iso(year, month, day), source: dayFirst[0], stated: true };
    }
  }

  // "September 12, 2026", "Sep 12"
  const monthFirst = new RegExp(
    `\\b(?:${WEEKDAY_WORD}\\.?,?\\s+)?${MONTH_WORD}\\.?\\s+(\\d{1,2})(?!\\d)(?:st|nd|rd|th)?(?:,?\\s+(\\d{4}))?`,
    'i',
  ).exec(line);
  if (monthFirst) {
    const month = MONTHS.findIndex((name) => name.startsWith(monthFirst[2]!.toLowerCase())) + 1;
    const day = Number(monthFirst[3]);
    const year = monthFirst[4] === undefined ? yearFor(month, day, today) : Number(monthFirst[4]);
    if (month > 0 && real(year, month, day)) {
      return { date: iso(year, month, day), source: monthFirst[0], stated: true };
    }
  }

  if (/\btoday\b/.test(lower)) {
    return { date: today, source: /today/i.exec(line)![0], stated: true };
  }
  if (/\btomorrow\b/.test(lower)) {
    return { date: shiftDays(today, 1), source: /tomorrow/i.exec(line)![0], stated: true };
  }

  // "next Tuesday", "this Friday", a bare "Saturday" — the next one to come.
  const named = new RegExp(`\\b(next|this|on)?\\s*${WEEKDAY_WORD}\\b`, 'i').exec(line);
  if (named) {
    const wanted = WEEKDAYS.findIndex((name) => name.startsWith(named[2]!.toLowerCase()));
    if (wanted >= 0) {
      const from = weekdayOf(today);
      let ahead = (wanted - from + 7) % 7;
      if (ahead === 0) ahead = 7; // "Tuesday" said on a Tuesday means the next one
      if ((named[1] ?? '').toLowerCase() === 'next' && ahead < 7) ahead += 0;
      return { date: shiftDays(today, ahead), source: named[0].trim(), stated: true };
    }
  }

  // "12/09/2026" — day-first or month-first is genuinely ambiguous, so it is read day-first (the
  // majority of the world) and marked unstated, which flags the form instead of guessing quietly.
  const numeric = /\b(\d{1,2})[/.](\d{1,2})[/.](\d{4})\b/.exec(line);
  if (numeric) {
    const [source, first, second, year] = numeric;
    const day = Number(first);
    const month = Number(second);
    if (real(Number(year), month, day)) {
      return { date: iso(Number(year), month, day), source, stated: day > 12 };
    }
  }
  return undefined;
}

/** `7:30pm`, `19:45`, `7pm`, and the ranges they appear in. */
function findTime(line: string): FoundTime | undefined {
  const clock = String.raw`(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)?`;
  const range = new RegExp(`\\b${clock}\\s*(?:-|–|—|to|until)\\s*${clock}\\b`, 'i').exec(line);
  const at = (hour: number, minute: number, suffix: string | undefined): string | undefined => {
    let value = hour;
    const meridiem = suffix?.toLowerCase();
    if (meridiem === 'pm' && value < 12) value += 12;
    if (meridiem === 'am' && value === 12) value = 0;
    return value > 23 || minute > 59 ? undefined : `${pad(value)}:${pad(minute)}`;
  };

  if (range) {
    // "7–9pm": a meridiem on the end applies to the start too, unless the start has its own.
    const endMeridiem = range[6] ?? range[3];
    const start = at(Number(range[1]), Number(range[2] ?? 0), range[3] ?? endMeridiem);
    const end = at(Number(range[4]), Number(range[5] ?? 0), endMeridiem);
    if (start !== undefined && end !== undefined) {
      return { start, ...(end === start ? {} : { end }), source: range[0] };
    }
  }

  // A lone time needs either a meridiem or a colon: a bare "12" in a title is not a time.
  const single = new RegExp(
    `\\b(\\d{1,2})(?:[:.](\\d{2}))?\\s*(am|pm)\\b|\\b(\\d{1,2}):(\\d{2})\\b`,
    'i',
  ).exec(line);
  if (single) {
    const start =
      single[3] === undefined
        ? at(Number(single[4]), Number(single[5] ?? 0), undefined)
        : at(Number(single[1]), Number(single[2] ?? 0), single[3]);
    if (start !== undefined) return { start, source: single[0] };
  }
  return undefined;
}

const SEPARATORS = /^[\s\-–—:,|@·•>]+|[\s\-–—:,|@·•<]+$/g;

const escape = (value: string): string => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/**
 * What's left of a line once the date and time have been taken out of it.
 *
 * A connective goes only when it was holding the date or time on ("dentist **at** 9am"); on its
 * own it is part of what the event is called, and "Away at Celtic" must not become "Away Celtic".
 */
function titleFrom(line: string, locale: string, ...used: (string | undefined)[]): string {
  let rest = line;
  for (const part of used) {
    if (part === undefined || part === '') continue;
    rest = rest.replace(
      new RegExp(
        `(?:(?<!\\p{L})(?:at|on|from|starts?|kick[- ]?off|${CALENDAR_LANGUAGES[locale]!.connectors || '(?!)'})\\s+)?${escape(part)}`,
        'iu',
      ),
      ' ',
    );
  }
  return (
    rest
      // Notes about a time that isn't there yet are not part of what the event is called.
      .replace(/\b(kick[- ]?off|doors|starts?)\b\s*(tbc|tba|to be confirmed|to follow)?/gi, ' ')
      .replace(/\b(tbc|tba|to be confirmed|time to follow)\b/gi, ' ')
      .replace(/\s{2,}/g, ' ')
      // Punctuation left stranded where the date and time used to be.
      .replace(/([,;|·•-])\s*(?=[,;|·•-])/g, '')
      .replace(/\s{2,}/g, ' ')
      .replace(SEPARATORS, '')
      .trim()
  );
}

const ALL_DAY = /\ball[- ]day\b/i;
const NO_TIME_YET = /\b(tbc|tba|time to follow|to be confirmed)\b/i;

/**
 * Read every event in a piece of text. Lines are the unit, because the things people paste — a
 * fixture list, a season's concerts, a line from a message — put one event on one line, and a
 * date on its own line applies to what follows it.
 */
export function parseEvents(
  text: string,
  options: ParseEventsOptions,
): readonly IntakeExtraction[] {
  const locale = calendarLocale(options.locale);
  const dateIn = (line: string): FoundDate | undefined =>
    (/\d{4}-\d{2}-\d{2}|\d{1,2}[/.]\d{1,2}[/.]\d{4}/.test(line)
      ? findDate(line, options.today)
      : undefined) ??
    localizedDate(line, locale, (english) => findDate(english, options.today)) ??
    findDate(line, options.today);
  const timeIn = (line: string): FoundTime | undefined =>
    localizedTime(line, locale, findTime) ?? findTime(line);
  const allDayWords = calendarWords(CALENDAR_LANGUAGES[locale]!.allDay, locale);
  const lines = text
    .normalize('NFC')
    .split(/\r?\n/)
    .map((line) => line.trim());
  const found: IntakeExtraction[] = [];
  let carriedDate: string | undefined;

  lines.forEach((line, index) => {
    if (line === '') return;
    const date = dateIn(line);
    // Remove the date first: an ISO date must never be mistaken for a clock range.
    const time = timeIn(date ? line.replace(date.source, ' ') : line);
    if (date === undefined && time === undefined) return;
    // A time under a date line belongs to that date — how a day's schedule is written.
    const day = date?.date ?? carriedDate;
    if (day === undefined) return;
    if (date !== undefined) carriedDate = date.date;

    let title = titleFrom(line, locale, date?.source, time?.source, allDayWords.exec(line)?.[0]);
    let titleStated = title !== '';

    // "Sat 12 Sep" with times listed underneath is a heading for them, not an event itself.
    const next = lines.slice(index + 1).find((candidate) => candidate !== '');
    const nextInherits =
      next !== undefined && dateIn(next) === undefined && timeIn(next) !== undefined;
    if (date !== undefined && time === undefined && !titleStated && nextInherits) return;

    if (!titleStated) {
      // A date on its own line, with the event named underneath it.
      const next = lines.slice(index + 1).find((candidate) => candidate !== '');
      if (next !== undefined && dateIn(next) === undefined && timeIn(next) === undefined) {
        title = next;
        titleStated = true;
      }
    }

    const allDay = time === undefined || ALL_DAY.test(line) || allDayWords.test(line);
    const draft: EventDraft = allDay
      ? { title, start: { kind: 'date', date: day } }
      : {
          title,
          start: {
            kind: 'dateTime',
            dateTime: `${day}T${time.start}`,
            ...(options.timeZone === undefined ? {} : { timeZone: options.timeZone }),
          },
          ...(time.end === undefined
            ? {}
            : {
                end: {
                  kind: 'dateTime',
                  // An end before the start is the next morning: "22:00–01:00" is one evening.
                  dateTime: `${time.end < time.start ? shiftDays(day, 1) : day}T${time.end}`,
                  ...(options.timeZone === undefined ? {} : { timeZone: options.timeZone }),
                },
              }),
        };

    // Same rubric the model path is scored against: what the source gave, weighted by what a
    // wrong one costs. A time nobody stated leaves the form flagged for a look.
    const timeStated = time !== undefined || ALL_DAY.test(line) || allDayWords.test(line);
    const confidence =
      (titleStated ? 0.35 : 0) + ((date?.stated ?? false) ? 0.45 : 0) + (timeStated ? 0.2 : 0);

    const assumptions: string[] = [];
    const assumptionCodes: NonNullable<IntakeExtraction['assumptionCodes']>[number][] = [];
    if (!timeStated) {
      assumptionCodes.push('all-day');
      assumptions.push(
        NO_TIME_YET.test(line)
          ? 'no time given yet — filled in as all-day'
          : 'no time given — filled in as all-day',
      );
    }
    if (date !== undefined && !date.stated) {
      assumptionCodes.push('day-month');
      assumptions.push(`read "${date.source}" as day/month — check it is not month/day`);
    }
    if (date === undefined) {
      assumptions.push('took the date from the line above');
      assumptionCodes.push('inherited-date');
    }
    if (!titleStated) {
      assumptions.push('no title on the line');
      assumptionCodes.push('missing-title');
    }

    found.push({ draft, confidence, assumptions, assumptionCodes });
  });

  return found;
}
