import { OCR_LANGUAGES } from './ocr-languages';

/**
 * Reading the words off a picture, on this machine, with a recogniser this site serves itself.
 *
 * The site's promise is that nothing you drop in leaves the page, and `connect-src 'self'` in the
 * Content-Security-Policy is the machine-checkable form of it. A recogniser from a CDN would have
 * cost that promise — a third party would see the IP of every visitor who attached a flyer, and
 * could serve arbitrary script onto this origin. So Tesseract is self-hosted instead: the worker,
 * the WASM core and the language model are all same-origin files under `/ocr/`, emitted from
 * `node_modules` by the build (see `ocrAssets` in vite.config.ts).
 *
 * What that costs, stated plainly rather than hidden: about 6.5 MB for English, plus the selected language model, and `'wasm-unsafe-eval'` plus
 * `worker-src 'self'` in the CSP. `connect-src 'self'` is untouched, which is the point.
 *
 * It is all fetched **on demand**, the first time someone attaches a picture, and cached in
 * IndexedDB afterwards. Someone pasting a fixture list never pays for any of it, and the proof is
 * the build: Tesseract lands in its own chunk, not the page's bundle.
 */

/** How the recogniser is fetched. Injectable so the paths and the degradation are testable. */
export type LoadEngine = (language: string) => Promise<Engine>;

interface Engine {
  recognize: (image: File) => Promise<{ data: { text: string } }>;
}

/** Long enough for a big photo on a slow machine, short enough not to hang the funnel. */
const TIMEOUT_MS = 120_000;

/** Where the build put the three files. `BASE_URL` always ends in '/', root or sub-path. */
const assets = (): string => new URL(`${import.meta.env.BASE_URL}ocr/`, location.origin).href;

const loadTesseract: LoadEngine = async (language) => {
  const { createWorker } = await import('tesseract.js');
  const base = assets();
  const worker = await createWorker(language === 'eng' ? 'eng' : `${language}+eng`, undefined, {
    // Every path overridden: the defaults point at jsdelivr, and a default that reaches a CDN is
    // exactly the thing this module exists to avoid.
    workerPath: `${base}worker.min.js`,
    corePath: `${base}tesseract-core-simd-lstm.wasm.js`,
    langPath: base,
    // A worker built from a Blob needs `worker-src blob:`; a same-origin script needs only 'self'.
    workerBlobURL: false,
  });
  return worker as unknown as Engine;
};

/**
 * The words in a picture, or `null` when there are none — including when the recogniser itself
 * could not be had. A "can't read it" is the funnel's existing, honest answer; a thrown error in
 * the middle of reading an attachment is not.
 */
export interface SiteOcr {
  read(file: File, onReady?: () => void, language?: string): Promise<string | null>;
}

export function createOcr(load: LoadEngine = loadTesseract): SiteOcr {
  /** Kept between reads: the worker costs a download and a startup, and people attach more than one. */
  const engines = new Map<string, Promise<Engine>>();

  return {
    async read(file: File, onReady?: () => void, language?: string): Promise<string | null> {
      const model = OCR_LANGUAGES[language ?? 'en'] ?? 'eng';
      try {
        let engine = engines.get(model);
        if (!engine) {
          engine = load(model);
          engines.set(model, engine);
        }
        // A File goes to Tesseract through FileReader, not through a fetch of a blob: URL — so
        // reading a picture makes no request of any kind, and `connect-src 'self'` still holds.
        const ready = await engine;
        onReady?.();
        const done = ready.recognize(file);
        const guard = new Promise<null>((resolve) => setTimeout(() => resolve(null), TIMEOUT_MS));
        const result = await Promise.race([done, guard]);
        const text = result === null ? '' : result.data.text.trim();
        return text === '' ? null : text;
      } catch {
        engines.delete(model); // willing to try again rather than staying broken
        return null;
      }
    },
  };
}
