/** Local calendar vocabulary. Intl supplies month/weekday names, including inflected forms. */
interface Vocabulary {
  readonly today: string;
  readonly tomorrow: string;
  readonly allDay: string;
  readonly connectors: string;
}

export const CALENDAR_LANGUAGES: Readonly<Record<string, Vocabulary>> = {
  en: { today: 'today', tomorrow: 'tomorrow', allDay: 'all-day|all day', connectors: 'at|on|from' },
  de: { today: 'heute', tomorrow: 'morgen', allDay: 'ganztägig', connectors: 'am|um|ab' },
  es: { today: 'hoy', tomorrow: 'mañana', allDay: 'todo el día', connectors: 'el|a las|desde' },
  fr: {
    today: "aujourd’hui|aujourd'hui",
    tomorrow: 'demain',
    allDay: 'toute la journée',
    connectors: 'le|à|de',
  },
  it: { today: 'oggi', tomorrow: 'domani', allDay: 'tutto il giorno', connectors: 'il|alle|dalle' },
  nl: {
    today: 'vandaag',
    tomorrow: 'morgen',
    allDay: 'hele dag|de hele dag',
    connectors: 'op|om|vanaf',
  },
  pl: { today: 'dzisiaj|dziś', tomorrow: 'jutro', allDay: 'cały dzień', connectors: 'w|we|o|od' },
  pt: {
    today: 'hoje',
    tomorrow: 'amanhã',
    allDay: 'dia inteiro|o dia todo',
    connectors: 'em|às|a|desde',
  },
  tr: { today: 'bugün', tomorrow: 'yarın', allDay: 'tüm gün', connectors: 'saat' },
  ru: { today: 'сегодня', tomorrow: 'завтра', allDay: 'весь день', connectors: 'в|во|с' },
  ja: { today: '今日', tomorrow: '明日', allDay: '終日', connectors: '' },
  ko: { today: '오늘', tomorrow: '내일', allDay: '종일|하루 종일', connectors: '' },
  'zh-Hans': { today: '今天', tomorrow: '明天', allDay: '全天', connectors: '' },
  'zh-Hant': { today: '今天', tomorrow: '明天', allDay: '全天', connectors: '' },
};

export const calendarLocale = (locale = 'en'): string =>
  Object.prototype.hasOwnProperty.call(CALENDAR_LANGUAGES, locale) ? locale : 'en';
const escape = (text: string): string => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const eastAsian = (locale: string): boolean => /^(ja|ko|zh)/.test(locale);
export function calendarWords(words: string, locale: string): RegExp {
  return new RegExp(
    eastAsian(locale) ? `(?:${words})` : `(?<![\\p{L}\\p{N}])(?:${words})(?![\\p{L}\\p{N}])`,
    'iu',
  );
}

const months = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];
const weekdays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const nameCache = new Map<string, { months: Map<string, number>; weekdays: Map<string, number> }>();
function names(locale: string): { months: Map<string, number>; weekdays: Map<string, number> } {
  const cached = nameCache.get(locale);
  if (cached) return cached;
  const result = { months: new Map<string, number>(), weekdays: new Map<string, number>() };
  for (const width of ['long', 'short'] as const) {
    for (let month = 0; month < 12; month += 1) {
      for (const day of [undefined, 'numeric'] as const) {
        const parts = new Intl.DateTimeFormat(locale, {
          month: width,
          day,
          timeZone: 'UTC',
        }).formatToParts(new Date(Date.UTC(2026, month, 15)));
        const name = parts.find((part) => part.type === 'month')!.value.replace(/\.$/, '');
        result.months.set(name, month);
      }
    }
    for (let day = 0; day < 7; day += 1) {
      const name = new Intl.DateTimeFormat(locale, { weekday: width, timeZone: 'UTC' })
        .format(new Date(Date.UTC(2026, 0, 4 + day)))
        .replace(/\.$/, '');
      result.weekdays.set(name, day);
    }
  }
  nameCache.set(locale, result);
  return result;
}

/** Use the existing date validator/year policy, but retain the exact original span for titles. */
export function localizedDate<T extends { source: string }>(
  line: string,
  locale: string,
  parse: (english: string) => T | undefined,
): T | undefined {
  if (locale === 'en') return undefined;
  const accept = (source: string, english: string): T | undefined => {
    const found = parse(english);
    // A weekday immediately before a full date describes that date, not the title.
    const before = line.slice(0, line.indexOf(source));
    for (const [name] of names(locale).weekdays) {
      const prefix = new RegExp(`(?:${escape(name)})[.,]?\\s*$`, 'iu').exec(before);
      if (prefix) {
        source = prefix[0] + source;
        break;
      }
    }
    return found ? { ...found, source } : undefined;
  };
  const vocab = CALENDAR_LANGUAGES[locale]!;
  // Numeric East Asian dates: optional year; no word boundaries between ideographs and digits.
  if (eastAsian(locale)) {
    const date = /(?:(\d{4})\s*[年년]\s*)?(\d{1,2})\s*[月월]\s*(\d{1,2})\s*[日일]/u.exec(line);
    if (date)
      return accept(
        date[0],
        `${date[3]} ${months[Number(date[2]) - 1] ?? 'invalid'} ${date[1] ?? ''}`,
      );
  } else {
    for (const [name, month] of [...names(locale).months].sort(
      (a, b) => b[0].length - a[0].length,
    )) {
      const token = escape(name);
      const match = new RegExp(
        `(?<![\\p{L}\\p{N}])(\\d{1,2})[.º°]?\\s+(?:de\\s+)?${token}\\.?(?!\\p{L})(?:\\s+(?:de\\s+)?(\\d{4}))?`,
        'iu',
      ).exec(line);
      if (match) return accept(match[0], `${match[1]} ${months[month]} ${match[2] ?? ''}`);
      const reverse = new RegExp(
        `(?<!\\p{L})${token}\\.?\\s+(\\d{1,2})(?!\\d)(?:,?\\s+(\\d{4}))?`,
        'iu',
      ).exec(line);
      if (reverse) return accept(reverse[0], `${reverse[1]} ${months[month]} ${reverse[2] ?? ''}`);
    }
  }
  for (const [words, english] of [
    [vocab.today, 'today'],
    [vocab.tomorrow, 'tomorrow'],
  ]) {
    const match = calendarWords(words!, locale).exec(line);
    if (match) return accept(match[0], english!);
  }
  for (const [name, day] of [...names(locale).weekdays].sort((a, b) => b[0].length - a[0].length)) {
    const match = calendarWords(escape(name), locale).exec(line);
    if (match) return accept(match[0], weekdays[day]!);
  }
  return undefined;
}

/** Local clock markers, meridiems, and range connectors; never translate event titles. */
export function localizedTime<T extends { source: string }>(
  line: string,
  locale: string,
  parse: (english: string) => T | undefined,
): T | undefined {
  if (locale === 'en') return undefined;
  const prefix = '(上午|下午|晚上|早上|午前|午後|오전|오후)?';
  const unit = eastAsian(locale) ? '[时時点點시]' : '(?:h|heures?|Uhr|uur)';
  const clock = `${prefix}\\s*(\\d{1,2})(?:(?:[:：](\\d{2}))|(?:\\s*${unit}(?:\\s*(\\d{1,2})\\s*(?:分|분)?)?))`;
  const pattern = new RegExp(
    `(?<![\\p{L}\\p{N}])${clock}(?:\\s*(?:-|–|—|~|〜|～|至|到|부터|から|bis|a|à|até|tot|do|до)\\s*${clock})?`,
    'iu',
  );
  // CJK clocks can directly follow a title or date.
  const match = (
    eastAsian(locale)
      ? new RegExp(pattern.source.replace('(?<![\\p{L}\\p{N}])', ''), 'iu')
      : pattern
  ).exec(line);
  if (!match || /^\s*[ap]m\b/i.test(line.slice(match.index + match[0].length))) return undefined;
  const render = (offset: number, fallback?: string): string => {
    const period = match[offset] || fallback;
    const suffix = period ? (/下午|晚上|午後|오후/.test(period) ? 'pm' : 'am') : '';
    return `${match[offset + 1]}:${(match[offset + 2] ?? match[offset + 3] ?? '0').padStart(2, '0')}${suffix}`;
  };
  const normalized = render(1, match[5]) + (match[6] ? `–${render(5, match[1])}` : '');
  const found = parse(normalized);
  return found ? { ...found, source: match[0] } : undefined;
}
