import { runFunnel, type FunnelResult, type IntakeProgress } from './intake';

export type IntakeReply =
  | { readonly kind: 'progress'; readonly stage: IntakeProgress }
  | { readonly kind: 'result'; readonly result: FunnelResult }
  | { readonly kind: 'error' };

self.onmessage = async (
  event: MessageEvent<{ typed: string; file: File | null; language?: string }>,
) => {
  const send = (reply: IntakeReply): void => self.postMessage(reply);
  try {
    const result = await runFunnel(
      event.data.typed,
      event.data.file,
      (stage) => {
        send({ kind: 'progress', stage });
      },
      event.data.language,
    );
    send({ kind: 'result', result });
  } catch {
    send({ kind: 'error' });
  }
};
